/**
 * Cross-check the browser sampling implementation against backend fixtures.
 *
 * The fixtures are generated by backend/scripts/generate_sampling_fixtures.py
 * from backend/app/services/sampling.py. This script loads the same
 * src/utils/sampling.ts module used by the UI (compiled in-memory with the
 * existing `typescript` devDependency, so no new package is required) and
 * asserts every probability within 1e-6.
 *
 * Run from frontend/:
 *   npm run test:sampling
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const frontendDir = path.resolve(scriptDir, '..');
const sourcePath = path.join(frontendDir, 'src', 'utils', 'sampling.ts');
const fixturePath = path.join(
  frontendDir,
  'tests',
  'fixtures',
  'sampling_cases.json'
);

const source = fs.readFileSync(sourcePath, 'utf8');
const compiled = ts.transpileModule(source, {
  compilerOptions: {
    module: ts.ModuleKind.CommonJS,
    target: ts.ScriptTarget.ES2020,
  },
  fileName: sourcePath,
}).outputText;

const moduleShim = { exports: {} };
const loadModule = new Function('exports', 'module', 'require', compiled);
loadModule(moduleShim.exports, moduleShim, (name) => {
  throw new Error(`Unexpected require("${name}") while loading sampling.ts`);
});
const { computeDistribution } = moduleShim.exports;

if (typeof computeDistribution !== 'function') {
  throw new Error('sampling.ts did not export computeDistribution');
}

const fixture = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const tolerance = Number(fixture.tolerance ?? 1e-6);
const failures = [];

for (const testCase of fixture.cases) {
  const actual = computeDistribution(
    testCase.items,
    testCase.params,
    testCase.mode
  );
  const expected = testCase.expected;

  if (actual.length !== expected.length) {
    failures.push(
      `${testCase.name}: length ${actual.length} != ${expected.length}`
    );
    continue;
  }

  for (let index = 0; index < expected.length; index += 1) {
    const got = actual[index];
    const want = expected[index];
    if (!Number.isFinite(got) || Math.abs(got - want) > tolerance) {
      failures.push(
        `${testCase.name}[${index}]: frontend=${got} backend=${want} ` +
          `diff=${Number.isFinite(got) ? Math.abs(got - want) : 'NaN'}`
      );
      break;
    }
  }

  if (expected.length > 0) {
    const total = actual.reduce((sum, value) => sum + value, 0);
    if (Math.abs(total - 1) > tolerance) {
      failures.push(`${testCase.name}: probability sum ${total} != 1`);
    }
  }
}

if (failures.length > 0) {
  console.error(`Sampling cross-check FAILED (${failures.length} issue(s)):`);
  for (const failure of failures) {
    console.error(`  - ${failure}`);
  }
  process.exitCode = 1;
} else {
  const detail = fixture.cases
    .map((testCase) => `${testCase.name} (${testCase.mode})`)
    .join(', ');
  console.log(
    `Sampling cross-check passed: ${fixture.cases.length} cases within ${tolerance}`
  );
  console.log(`  ${detail}`);
}
